mapper.select:
SELECT system_id, item_id, object_id, MAX(id) as max_id
FROM eval_patrol_inspection
WHERE deleted = 0

    AND item_id = #{itemId}


    AND object_id = #{objectId}


    AND address_coding = #{addressCoding}

GROUP BY system_id, item_id, object_id
ORDER BY max_id DESC
LIMIT #{pageSize} OFFSET #{offset}

SELECT COUNT(*) FROM (
    SELECT system_id, item_id, object_id
    FROM eval_patrol_inspection
    WHERE deleted = 0

        AND item_id = #{itemId}


        AND object_id = #{objectId}


        AND address_coding = #{addressCoding}

    GROUP BY system_id, item_id, object_id
) AS grouped
